"""Build a self-contained local running-order page from the saved edition."""
from html import escape
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
manifest = json.loads((HERE / 'manifest.json').read_text())
def time(value):
    return f'{int(value)//60:02}:{int(value)%60:02}'

images = ['01-signal', '02-refraction', '03-matter', '04-identity', '05-human', '06-singularity', '07-home']
cards = []
for i, chapter in enumerate(manifest['chapters']):
    shots = [s for s in manifest['shots'] if s['chapter'] == chapter['name']]
    start = chapter['start']
    rows = []
    for shot in shots:
        rows.append(f'<li><time>{time(start)}</time><span>{escape(shot["title"])}</span><small>{escape(shot["view"])} · {shot["seconds"]:g}s</small></li>')
        start += shot['seconds']
    cards.append(f'''<article id="chapter-{i+1}"><img src="stills/{images[i]}.jpg" alt="Actual application render from {escape(chapter['name'])}" loading="lazy">
      <div class="chapter"><p class="eyebrow">{time(chapter['start'])} — {time(chapter['end'])}</p><h2>{escape(chapter['name'])}</h2><p>{escape(chapter['description'])}</p>
      <details><summary>View {len(shots)} directed shots</summary><ol>{''.join(rows)}</ol></details></div></article>''')

html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VERSION1 · From Signal to Spectacle</title>
<style>
:root{color-scheme:dark;--ink:#f2f0e9;--muted:#b3b7be;--line:#30333c;--accent:#bdff94}*{box-sizing:border-box}body{margin:0;background:#0b0c10;color:var(--ink);font:17px/1.6 system-ui,sans-serif}a{color:var(--accent);text-underline-offset:4px}header,main,footer{max-width:1160px;margin:auto;padding:40px 32px}.top{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line);padding-bottom:20px;font-size:12px;letter-spacing:.16em;text-transform:uppercase}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.13em;color:var(--accent);margin:0 0 16px}h1{font-size:clamp(44px,7.5vw,96px);font-weight:600;line-height:1.04;letter-spacing:-.06em;max-width:950px;margin:54px 0 24px}h2{font-size:clamp(24px,3vw,36px);line-height:1.15;letter-spacing:-.035em;margin:0 0 20px}.intro{font-size:21px;max-width:780px;color:var(--muted)}.facts{display:flex;gap:28px;flex-wrap:wrap;margin:32px 0}.facts b{font-size:28px;font-weight:500}.facts span{display:block;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.1em}video{width:100%;display:block;background:black;border:1px solid var(--line);aspect-ratio:16/9}nav{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}.note{color:var(--muted);font-size:14px}.section-label{margin:64px 0 24px;display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid var(--line);padding-bottom:16px}article{display:grid;grid-template-columns:1.15fr 1fr;align-items:start;gap:36px;padding:36px 0;border-bottom:1px solid var(--line)}article>img{width:100%;aspect-ratio:16/9;object-fit:cover;background:black}.chapter p{color:var(--muted)}.chapter .eyebrow{color:var(--accent)}details{font-size:14px;margin-top:24px}summary{cursor:pointer;color:var(--accent)}ol{list-style:none;padding:0}li{display:grid;grid-template-columns:46px 1fr;gap:6px 12px;border-top:1px solid var(--line);padding:10px 0}li small{grid-column:2;color:var(--muted)}time{color:var(--muted);font-variant-numeric:tabular-nums}.companions{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.companions>div{border-top:2px solid var(--line);padding-top:24px}.companions h3{font-size:20px;line-height:1.3}.companions p{color:var(--muted);font-size:15px}.setup{background:#15181d;padding:28px 32px;margin-top:44px;border-left:3px solid var(--accent)}.setup p{margin:8px 0}.setup b{font-weight:600}footer{font-size:13px;color:var(--muted);border-top:1px solid var(--line);margin-top:48px}@media(max-width:760px){header,main,footer{padding:28px 20px}article{grid-template-columns:1fr;gap:22px}.companions{grid-template-columns:1fr}.top{font-size:10px}h1{margin-top:38px}.intro{font-size:18px}.setup{padding:20px}}
</style></head><body>
<header><div class="top"><strong>VERSION1 / Club Visuals</strong><span>Directed showcase · November 2026</span></div><h1>From Signal<br>to Spectacle.</h1><p class="intro">One light becomes a world. That world acquires an identity. Human movement brings it to life. Then everything resolves back to black.</p><div class="facts"><div><b>12:00</b><span>Complete journey</span></div><div><b>7</b><span>Chapters</span></div><div><b>29</b><span>Directed shots</span></div><div><b>61</b><span>Transitions in companion atlas</span></div></div></header>
<main><p class="eyebrow">Watch the 84-second preview · actual app output</p><video controls playsinline preload="metadata" poster="stills/04-identity.jpg" src="../downloads/version1_showcase_signal_to_spectacle_trailer.mp4"></video><p class="note">Silent preview film · 1280 × 720 · the saved 12-minute playlist contains the full edit.</p><nav><a href="http://localhost:8008/redesign#playlist">Open application playlists ↗</a><a href="../downloads/version1_showcase_signal_to_spectacle_trailer.mp4" download>Download preview MP4</a><a href="README.md">Operator running sheet</a><a href="CAPABILITIES.md">Capability map</a></nav>
<div class="setup"><b>To play the complete show</b><p>In Playlists, select <strong>VERSION1 · From Signal to Spectacle · 12 min</strong>. Use 16:9, captions off, source audio muted and playlist looping off. Preview first, then use your normal output handover.</p><p class="note">A reusable model is also saved in Show Builder. The package was created without starting live output or opening a camera or microphone.</p></div>
<div class="section-label"><span class="eyebrow">The journey</span><span class="note">Seven actual application renders</span></div>
''' + ''.join(cards) + '''
<div class="section-label"><span class="eyebrow">Beyond the main film</span></div><section class="companions"><div><p class="eyebrow">4:16 · Saved playlist</p><h3>The Transition Atlas</h3><p>Every one of the app’s 61 transitions, presented across alternating footage. A complete visual reference after the cinematic show.</p></div><div><p class="eyebrow">1:36 + optional 1:04</p><h3>You are the signal</h3><p>Connect a camera for the Live Input Encore: movement mask, glow and distortion with logo/text layers. Follow with an operator-led audio-reactive Auto Perform finale.</p></div><div><p class="eyebrow">Production walkthrough</p><h3>From capture to creation</h3><p>Reload and sort the library, inspect virtual cues, pause logo animation, resume the Show Builder edition, then record a portrait render and reuse it as a source.</p></div></section>
<div class="setup"><b>A complete showcase, with a deliberate distinction</b><p>The main film runs without hardware. Its human-motion sequence was processed from existing recorded footage through the real motion extractor. The live encore requires a camera you explicitly connect; audio reactivity requires a connected music input.</p><p class="note">No music is bundled. For a scored performance, 120 BPM fits the 16- and 32-second phrases. See the running sheet for the musical arc and live handover.</p></div>
</main><footer>Created with Club Visuals’ native video, canvas and WebGL processing. Existing source videos and shows are preserved. Staged playlists, reusable recipes and verification reports accompany this running order.</footer></body></html>'''
(HERE / 'index.html').write_text(html)
print('Built showcase/index.html')
